// (agent work) to HEAD (what was committed).
func TestCondenseSession_IncludesInitialAttribution(t *testing.T) {
	dir := t.TempDir()
	repo, err := git.PlainInit(dir, false)
	if err != nil {
		t.Fatalf("failed to init repo: %v", err)
	}

	// Create initial commit with a file
